global_css:
/* UptimeFixer Safe Changes Manager - footer redesign v1.1 */
.ufx-safe-footer,
.ufx-safe-footer * { box-sizing: border-box; }
.ufx-safe-footer {
    position: relative;
    width: 100%;
    overflow: hidden;
    background: #101f2c;
    color: #f7fbff;
    font-family: inherit;
    border-top: 1px solid rgba(255,255,255,.07);
}
.ufx-safe-footer::before {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    height: 3px;
    background: #c8f15a;
    opacity: .9;
}
.ufx-safe-footer__inner {
    width: min(1320px, calc(100% - 56px));
    margin: 0 auto;
    padding: 68px 0 22px;
}
.ufx-safe-footer__top {
    display: grid;
    grid-template-columns: minmax(300px, .95fr) minmax(620px, 1.55fr);
    gap: 84px;
    align-items: start;
}
.ufx-safe-footer__brand { max-width: 430px; }
.ufx-safe-footer__logo {
    display: inline-flex;
    align-items: center;
    justify-content: flex-start;
    max-width: 100%;
    margin: 0 0 28px;
    text-decoration: none !important;
}
.ufx-safe-footer__logo img,
.ufx-safe-footer__logo .custom-logo {
    display: block;
    width: auto;
    max-width: 230px;
    max-height: 68px;
    height: auto;
    object-fit: contain;
    background: #ffffff;
    padding: 8px 12px;
    border: 1px solid rgba(255,255,255,.16);
    border-radius: 12px;
    box-shadow: 0 12px 32px rgba(0,0,0,.14);
}
.ufx-safe-footer__logo .custom-logo-link { display: inline-flex; }
.ufx-safe-footer__logo-text {
    color: #fff;
    font-size: 26px;
    font-weight: 700;
    letter-spacing: -.02em;
}
.ufx-safe-footer__eyebrow {
    margin: 0 0 12px;
    color: #c8f15a;
    font-size: 12px;
    line-height: 1.2;
    font-weight: 700;
    letter-spacing: .16em;
}
.ufx-safe-footer__brand h2 {
    margin: 0;
    color: #ffffff;
    font-size: clamp(38px, 3.7vw, 54px);
    line-height: 1.02;
    letter-spacing: -.045em;
    font-weight: 700;
}
.ufx-safe-footer__brand h2 span { color: #dafa86; }
.ufx-safe-footer__intro {
    max-width: 390px;
    margin: 22px 0 0;
    color: rgba(239,245,250,.70);
    font-size: 16px;
    line-height: 1.75;
}
.ufx-safe-footer__cta {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-height: 44px;
    margin-top: 26px;
    padding: 10px 17px;
    border: 1px solid #c8f15a;
    border-radius: 999px;
    background: #c8f15a;
    color: #10202d !important;
    text-decoration: none !important;
    font-size: 14px;
    line-height: 1;
    font-weight: 700;
    transition: transform .18s ease, background .18s ease, border-color .18s ease;
}
.ufx-safe-footer__cta:hover {
    transform: translateY(-2px);
    background: #ddff86;
    border-color: #ddff86;
}
.ufx-safe-footer__nav {
    display: grid;
    grid-template-columns: 1.45fr .85fr .85fr;
    gap: 54px;
    padding-top: 6px;
}
.ufx-safe-footer__nav section { min-width: 0; }
.ufx-safe-footer__nav h3 {
    margin: 0 0 22px;
    color: #ffffff;
    font-size: 13px;
    line-height: 1.2;
    font-weight: 700;
    letter-spacing: .12em;
    text-transform: uppercase;
}
.ufx-safe-footer__nav ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.ufx-safe-footer__tools ul {
    display: grid;
    grid-template-columns: 1fr 1fr;
    column-gap: 30px;
}
.ufx-safe-footer__nav li { margin: 0 0 14px; }
.ufx-safe-footer__nav a {
    display: inline-flex;
    color: rgba(235,242,248,.72);
    text-decoration: none !important;
    font-size: 15px;
    line-height: 1.45;
    transition: color .18s ease, transform .18s ease;
}
.ufx-safe-footer__nav a:hover {
    color: #c8f15a;
    transform: translateX(2px);
}
.ufx-safe-footer__bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    margin-top: 56px;
    padding-top: 20px;
    border-top: 1px solid rgba(255,255,255,.10);
}
.ufx-safe-footer__bottom p {
    margin: 0;
    color: rgba(231,239,246,.58);
    font-size: 13px;
    line-height: 1.5;
}
.ufx-safe-footer__bottom a {
    color: #79aaff;
    text-decoration: none !important;
    font-weight: 600;
}
.ufx-safe-footer__bottom a:hover { color: #c8f15a; }
.ufx-safe-footer__heart { color: #ff6570; }
@media (max-width: 1080px) {
    .ufx-safe-footer__inner { width: min(100% - 44px, 1320px); }
    .ufx-safe-footer__top { grid-template-columns: 1fr; gap: 48px; }
    .ufx-safe-footer__brand { max-width: 650px; }
    .ufx-safe-footer__nav { grid-template-columns: 1.25fr 1fr 1fr; gap: 36px; }
}
@media (max-width: 720px) {
    .ufx-safe-footer__inner { width: min(100% - 32px, 1320px); padding-top: 52px; }
    .ufx-safe-footer__top { gap: 40px; }
    .ufx-safe-footer__logo { margin-bottom: 24px; }
    .ufx-safe-footer__logo img,
    .ufx-safe-footer__logo .custom-logo { max-width: 205px; }
    .ufx-safe-footer__brand h2 { font-size: 39px; }
    .ufx-safe-footer__intro { font-size: 15px; }
    .ufx-safe-footer__nav { grid-template-columns: 1fr 1fr; gap: 32px 28px; }
    .ufx-safe-footer__tools { grid-column: 1 / -1; }
    .ufx-safe-footer__bottom { flex-direction: column; align-items: flex-start; gap: 8px; margin-top: 42px; }
}
@media (max-width: 460px) {
    .ufx-safe-footer__inner { width: min(100% - 28px, 1320px); }
    .ufx-safe-footer__nav { grid-template-columns: 1fr; }
    .ufx-safe-footer__tools { grid-column: auto; }
    .ufx-safe-footer__tools ul { grid-template-columns: 1fr 1fr; column-gap: 22px; }
    .ufx-safe-footer__brand h2 { font-size: 36px; }
    .ufx-safe-footer__cta { width: 100%; justify-content: center; }
}
